import React, { useState } from 'react';
import './AdminPage.css'; // AdminPage 전용 스타일
import AccountInfoTab from './components/AccountInfoTab';
import MemberManagementTab from './components/MemberManagementTab';
import ContentManagementTab from './components/ContentManagementTab';
import AdminInquiryBoardTab from './components/AdminInquiryBoardTab';
import SiteStatisticsTab from './components/SiteStatisticsTab';

const AdminPage = () => {
  const [activeTab, setActiveTab] = useState('accountInfo'); // 기본 탭: 계정 정보

  // 가상의 관리자 계정 정보
  const adminInfo = {
    name: '최고 관리자',
    email: 'admin@example.com',
    role: '시스템 관리자',
    lastLogin: '2025-07-10 11:00 AM',
  };

  const renderTabContent = () => {
    switch (activeTab) {
      case 'accountInfo':
        return <AccountInfoTab adminInfo={adminInfo} />;
      case 'memberManagement':
        return <MemberManagementTab />;
      case 'contentManagement':
        return <ContentManagementTab />;
      case 'adminInquiryBoard':
        return <AdminInquiryBoardTab />;
      case 'siteStatistics':
        return <SiteStatisticsTab />;
      default:
        return <AccountInfoTab adminInfo={adminInfo} />;
    }
  };

  return (
    <div className="admin-page-container">
      <h1 className="admin-page-title">관리자 페이지 ⚙️</h1>
      <div className="admin-page-tabs">
        <button
          className={`tab-button ${activeTab === 'accountInfo' ? 'active' : ''}`}
          onClick={() => setActiveTab('accountInfo')}
        >
          계정 정보
        </button>
        <button
          className={`tab-button ${activeTab === 'memberManagement' ? 'active' : ''}`}
          onClick={() => setActiveTab('memberManagement')}
        >
          회원 관리
        </button>
        <button
          className={`tab-button ${activeTab === 'contentManagement' ? 'active' : ''}`}
          onClick={() => setActiveTab('contentManagement')}
        >
          콘텐츠 관리
        </button>
        <button
          className={`tab-button ${activeTab === 'adminInquiryBoard' ? 'active' : ''}`}
          onClick={() => setActiveTab('adminInquiryBoard')}
        >
          문의 게시판
        </button>
        <button
          className={`tab-button ${activeTab === 'siteStatistics' ? 'active' : ''}`}
          onClick={() => setActiveTab('siteStatistics')}
        >
          사이트 통계
        </button>
      </div>
      <div className="admin-page-content">
        {renderTabContent()}
      </div>
    </div>
  );
};

export default AdminPage;
